			var query = connection.prepareTupleQuery("""
					SELECT ?s WHERE {
					  ?s <urn:p> <urn:tag>
					  OPTIONAL { ?s <urn:lookup> ?key }
					  FILTER EXISTS { ?key <urn:end> <urn:tag> }
					}
					ORDER BY STABLE_INDEX(?s)
					""");
			assertThat(rows(query)).containsExactlyElementsOf(driver);
